class Widget {};

// CORRECT way to handle a dynamic array with a smart pointer:
// Use the specialized unique_ptr for arrays.
void correct_array_management() {
    auto u_ptr_arr = std::make_unique<Widget[]>(5);
    u_ptr_arr[3] = Widget{}; // OK: operator[] is provided
} // u_ptr_arr is automatically deallocated with delete[]

// INCORRECT way: Faking array support in shared_ptr
void incorrect_array_management() {
    // This compiles, but is a "horrible idea" according to Meyers.
    std::shared_ptr<Widget> s_ptr_arr(new Widget[5], 
                                      [](Widget* p) { delete[] p; });

    // No operator[] is available. Access requires pointer arithmetic.
    // *(s_ptr_arr.get() + 3) = Widget{}; // Awkward and error-prone

    // There is no std::shared_ptr<T[]> specialization
    // std::shared_ptr<Widget[]> s_ptr_arr_typed; // Compile error
}
